code.text:
interface eth0 {
  AdvSendAdvert on;
  AdvManagedFlag on;      # M: addresses from DHCPv6
  AdvOtherConfigFlag on;  # O: options from DHCPv6
  prefix 2001:db8:10::/64 { AdvAutonomous off; };   # disable SLAAC
};

resource "aws_subnet" "v6only" {
  vpc_id                                         = aws_vpc.main.id
  ipv6_native                                    = true
  ipv6_cidr_block                                = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  enable_dns64                                   = true
  enable_resource_name_dns_aaaa_record_on_launch = true
}
resource "aws_route" "nat64" {
  route_table_id              = aws_route_table.v6only.id
  destination_ipv6_cidr_block = "64:ff9b::/96"
  nat_gateway_id              = aws_nat_gateway.a.id
}

table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept
    iif lo accept
    meta l4proto ipv6-icmp accept          # NDP needs this
    tcp dport { 22, 443 } accept
  }
}
